use digimon_engine::{deck_tools,format};
#[test] fn authored_fifty_copy_rule_reaches_shared_database_and_validator(){assert_eq!(deck_tools::card_database()["EX2-046"].max_count_in_deck,50);let ids=vec!["EX2-046".to_owned();50];assert!(deck_tools::validate_deck(&ids).is_valid);}
#[test] fn ordinary_cards_keep_default_intrinsic_limit(){assert_eq!(deck_tools::card_database()["ST1-02"].max_count_in_deck,4);}
#[test] fn explicit_restrictions_and_singleton_still_dominate_printed_allowance(){let mut f=format::list_formats()[0].clone();f.rarity_policy=format::RarityPolicy::All;f.singleton=false;f.restriction.card_limits.clear();assert_eq!(deck_tools::card_legality_for_descriptor("EX2-046",&f).max_copies,50);f.restriction.card_limits.insert("EX2-046".into(),1);assert_eq!(deck_tools::card_legality_for_descriptor("EX2-046",&f).max_copies,1);f.restriction.card_limits.insert("EX2-046".into(),0);assert!(!deck_tools::card_legality_for_descriptor("EX2-046",&f).legal);f.restriction.card_limits.clear();f.singleton=true;assert_eq!(deck_tools::card_legality_for_descriptor("EX2-046",&f).max_copies,1);}
